INSERT OR REPLACE INTO "IMPORT Gross Sales" SELECT coalesce(k0."Customer", error('cells name a member Customer does not have: ' || c."Customer")), coalesce(k1."Material", error('cells name a member Material does not have: ' || c."Material")), coalesce(k2."Years", error('cells name a member Years does not have: ' || c."Years")), coalesce(k3."Months", error('cells name a member Months does not have: ' || c."Months")), sum(c.value::DOUBLE)
FROM read_csv('cells/IMPORT Gross Sales.csv', header = true, all_varchar = true) c LEFT JOIN "dim Customer" k0 ON k0.name = c."Customer" LEFT JOIN "dim Material" k1 ON k1.name = c."Material" LEFT JOIN "dim Years" k2 ON k2.name = c."Years" LEFT JOIN "dim Months" k3 ON k3.name = c."Months"
GROUP BY ALL;
